const scoreLead = (l: typeof leads[number], weights = { financial:25, interaction:18, visit:14, simulation:10, proposal:12, response:9, deadline:6, fit:6 }) => {
  const financial = Math.min(100, (l.entry / Math.max(36000, l.budget * .1)) * 70 + (l.installment / 2500) * 20);
  const response = Math.max(15, 100 - l.response / 2.5);
  const deadline = Math.max(20, 105 - l.deadline * 8);
  const totalWeight = Object.values(weights).reduce((a,b)=>a+b,0);
  const score = (financial*weights.financial + l.interaction*10*weights.interaction + (l.visit?100:20)*weights.visit + (l.simulation?100:20)*weights.simulation + (l.proposal?100:10)*weights.proposal + response*weights.response + deadline*weights.deadline + l.fit*weights.fit) / totalWeight;
  return Math.round(score);
};

function Tag({ children, tone="slate" }: { children: React.ReactNode; tone?: "slate"|"green"|"amber"|"red"|"blue"|"purple" }) {
  return <span className={`tag tag-${tone}`}>{children}</span>;
}

function DataClass({ type="Dado demonstrativo" }: { type?: string }) {
  const tone = type.includes("real") ? "green" : type.includes("determin") ? "blue" : type.includes("heur") ? "amber" : "purple";
  return <Tag tone={tone as any}>{type}</Tag>;
}

function SectionHead({ title, eyebrow, action }: { title:string; eyebrow?:string; action?:React.ReactNode }) {
  return <div className="section-head"><div><p>{eyebrow || "ÉVORA INTELLIGENCE 1.0"}</p><h1>{title}</h1></div>{action}</div>;
}

function Metric({ label, value, delta, onClick, type="Dado demonstrativo" }: { label:string; value:string; delta?:string; onClick?:()=>void; type?:string }) {
  return <button className="metric" onClick={onClick}><span className="metric-top"><span>{label}</span><ChevronRight size={15}/></span><strong>{value}</strong>{delta && <small>{delta}</small>}<span className="metric-class">{type}</span></button>;
}

